sys_script_include.script:
var BaseTableUtils = Class.create();
BaseTableUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    //CHECA DUPLICIDADE NOME DA BASE
    checkNameDup: function() {
        var baseName = this.getParameter("sysparm_name_to_check");

        var grBase = new GlideRecord("x_1092529_bms_ba_0_bases");

        if (grBase.get("name", baseName)) {
            return "true";
        }
        return "false";
    },
    // FIM 1

    //CHECA DUPLICIDADE CIDADE + ESTADO
    checkCityStateDupe: function() {
        var baseCity = this.getParameter("sysparm_city_to_check");
        var baseState = this.getParameter("sysparm_state_to_check");

        if (!baseCity || !baseState) {
            return "false";
        }

        var grBase = new GlideRecord("x_1092529_bms_ba_0_bases");
        grBase.addQuery("city", baseCity);
        grBase.addQuery("state", baseState);
        grBase.query();

        if (grBase.next()) {
            return "true";
        }
        return "false";

    },
    //FIM2

	//CHECA DUPLICIDADE DE MANAGER
    checkMultipleManager: function() {
        var baseManager = this.getParameter("sysparm_userid");
        var grBase = new GlideRecord("x_1092529_bms_ba_0_bases");
        grBase.addQuery("base_manager", baseManager);
        grBase.query();

        if (grBase.getRowCount() >= 1) {
            // gs.addErrorMessage("This manager already runs another base. Please select a different one.");
            return "true";
        }
        return "false";

    },
	//FIM3

	//CHECA SE TEM VAGAS NA BASE
    checkVacancies: function() {
        var baseId = this.getParameter("sysparm_baseid");
        var grBase = new GlideRecord("x_1092529_bms_ba_0_bases");
		grBase.get(baseId);

        if (grBase.avaible_vacancies < 1) {
            // gs.addErrorMessage("Invalid submission. There is no spots left for this base.");
            return "true";
        }
        return "false";

    },
	//FIM4

	//PEGA MEMBROS DE UM MESMO GRUPO
    getGroupMembers: function(groupID) {
        var membersArray = [];
        var grGroupMember = new GlideRecord("sys_user_grmember");
        grGroupMember.addQuery("group", groupID);
        grGroupMember.query();
        while (grGroupMember.next()) {
            membersArray.push(grGroupMember.getValue('user'));
        }
        return membersArray.toString();
    },
	//FIM5


    type: 'BaseTableUtils'
});
